/*
 * Publication list renderer for the static GitHub Pages site.
 * Reads an ordinary, versioned JSON file generated by the ORCID/Crossref
 * GitHub Actions sync. The HTML contains a human-readable fallback list,
 * which remains visible if JavaScript, JSON loading, or the APIs fail.
 */
(function () {
  "use strict";

  function safeUrl(value) {
    if (typeof value !== "string") return null;
    try {
      var u = new URL(value, window.location.href);
      return u.protocol === "https:" ? u.href : null;
    } catch (error) {
      return null;
    }
  }

  // Show author names in publication order; safely build text nodes rather
  // than injecting metadata into HTML. Bold Brandon's name only.
  function authorName(author) {
    if (typeof author === "string") return author.trim();
    if (!author || typeof author !== "object") return "";
    return String(author.name || [author.given, author.family].filter(Boolean).join(" ")).trim();
  }

  function isBrandon(author) {
    if (!author) return false;
    if (typeof author === "object") {
      if (String(author.orcid || "").endsWith("0000-0002-6442-2355")) return true;
      var family = String(author.family || "").trim().toLowerCase();
      var given = String(author.given || "").trim();
      if (family === "corder" && /^(brandon|b)\b/i.test(given)) return true;
    }
    var name = authorName(author);
    return /\b(brandon(?:\s+d(?:ev)?\.?|\s+dev)?\s+corder|b\.?\s*(?:d\.?\s*)?corder|corder,?\s*(?:brandon|b\.?))/i.test(name);
  }

  function appendAuthors(li, authors) {
    if (!Array.isArray(authors) || !authors.length) return;
    var line = document.createElement("p");
    line.className = "publication-authors";
    authors.forEach(function (author, i) {
      var name = authorName(author);
      if (!name) return;
      if (line.childNodes.length) line.appendChild(document.createTextNode(", "));
      if (isBrandon(author)) {
        var strong = document.createElement("strong");
        strong.textContent = name;
        line.appendChild(strong);
      } else {
        line.appendChild(document.createTextNode(name));
      }
    });
    if (line.childNodes.length) li.appendChild(line);
  }

  function renderGroup(fragment, heading, records) {
    if (!records.length) return;
    var h3 = document.createElement("h3");
    h3.textContent = heading;
    fragment.appendChild(h3);
    var list = document.createElement("ul");
    list.className = "alt";
    records.forEach(function (record) {
      var li = document.createElement("li");
      var titleLink = document.createElement("a");
      titleLink.textContent = record.title;
      var url = safeUrl(record.url) ||
        (record.doi ? safeUrl("https://doi.org/" + encodeURIComponent(record.doi)) : null);
      if (url) {
        titleLink.href = url;
        titleLink.target = "_blank";
        titleLink.rel = "noopener noreferrer";
        li.appendChild(titleLink);
      } else {
        var strong = document.createElement("strong");
        strong.textContent = record.title;
        li.appendChild(strong);
      }
      appendAuthors(li, record.authors);
      var detail = document.createElement("p");
      detail.className = "publication-detail";
      var venue = document.createElement("em");
      venue.textContent = record.venue || "Scholarly publication";
      detail.appendChild(venue);
      if (record.year) {
        detail.appendChild(document.createTextNode(" · " + String(record.year)));
      }
      if (record.doi) {
        detail.appendChild(document.createTextNode(" · DOI: " + record.doi));
      }
      li.appendChild(detail);
      list.appendChild(li);
    });
    fragment.appendChild(list);
  }

  document.addEventListener("DOMContentLoaded", function () {
    var target = document.getElementById("publication-list");
    if (!target || typeof window.fetch !== "function") return;

    fetch("assets/data/publications.json", { cache: "no-store" })
      .then(function (response) {
        if (!response.ok) throw new Error("Publication dataset HTTP " + response.status);
        return response.json();
      })
      .then(function (data) {
        if (!data || !Array.isArray(data.publications)) {
          throw new Error("Unexpected publication dataset format");
        }
        var valid = data.publications.filter(function (item) {
          return item && typeof item.title === "string" && item.title.trim();
        }).sort(function (a, b) {
          return (Number(b.year) || 0) - (Number(a.year) || 0) ||
            String(a.title).localeCompare(String(b.title));
        });

        var journals = valid.filter(function (item) {
          return item.type !== "dissertation" &&
            item.type !== "other" &&
            item.type !== "book";
        });
        var others = valid.filter(function (item) {
          return item.type === "dissertation" ||
            item.type === "other" ||
            item.type === "book";
        });
        if (!valid.length) throw new Error("No valid publications in dataset");
        var previewLimit = Number(target.getAttribute("data-limit")) || 0;
        if (previewLimit > 0) {
          journals = journals.slice(0, previewLimit);
          others = []; // The homepage shows journal papers only.
        }
        var fragment = document.createDocumentFragment();
        renderGroup(fragment, previewLimit > 0 ? "Recent Papers" :
          "Journal Articles and Other Papers", journals);
        renderGroup(fragment, "Dissertations and Other Scholarly Work", others);
        target.replaceChildren(fragment);
      })
      .catch(function (error) {
        console.warn("Showing the saved publication list:", error);
      });
  });
}());
